		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := mustJSON(r, &req); err != nil {
		writeError(w, 400, "invalid_json", "Invalid JSON body")
		return
	}

	var statesJSON []byte
	err := db.DB.QueryRow(`SELECT function_states FROM locations WHERE location_id=$1`, req.LocationID).Scan(&statesJSON)
	if err != nil {
		writeError(w, 404, "not_found", "Location not found")
		return
	}

	var states map[string]bool
	if statesJSON != nil {
		json.Unmarshal(statesJSON, &states)
