	states[req.Function] = req.Active
	newStates, _ := json.Marshal(states)

	db.DB.Exec(`UPDATE locations SET function_states=$1, updated_at=NOW() WHERE location_id=$2`, newStates, req.LocationID)

	writeJSON(w, 200, map[string]any{
		"data": map[string]any{"locationId": req.LocationID, "function": req.Function, "active": req.Active},
	})
}

