	}

	// Check temperature
	var tempMin, tempMax float64
	err := db.DB.QueryRow(`SELECT temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, req.SampleID).
		Scan(&tempMin, &tempMax)
