	sampleTypes := []models.SampleType{}
	rows, _ := db.DB.Query(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types`)
