				"certifications": certs,
			},
			"sampleTypes": sampleTypes,
			"locations":   locations,
		},
	})
}

// GET /api/events (SSE stream)
func StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	// This is a simplified SSE implementation
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeError(w, 500, "internal_error", "Streaming not supported")
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")

	since := r.URL.Query().Get("since")
	sinceSeq := int64(0)
	if since != "" {
		sinceSeq, _ = strconv.ParseInt(since, 10, 64)
	}

	// Send existing events since sequence
	rows, err := db.DB.Query(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC`, sinceSeq)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var e models.RealtimeEvent
			var payloadJSON []byte
			rows.Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
			json.Unmarshal(payloadJSON, &e.Payload)
			data, _ := json.Marshal(e)
			fmt.Fprintf(w, "data: %s\n\n", data)
			flusher.Flush()
		}
	}

	// Keep connection open for new events
	lastSeq := sinceSeq
	for {
		var e models.RealtimeEvent
		var payloadJSON []byte
		err := db.DB.QueryRow(`SELECT event_id, sequence, event_type, audience, payload, timestamp::text FROM events WHERE sequence > $1 ORDER BY sequence ASC LIMIT 1`, lastSeq).
			Scan(&e.EventID, &e.Sequence, &e.EventType, &e.Audience, &payloadJSON, &e.Timestamp)
		if err == sql.ErrNoRows {
			time.Sleep(2 * time.Second)
			continue
		}
		if err != nil {
			break
		}
		json.Unmarshal(payloadJSON, &e.Payload)
		data, _ := json.Marshal(e)
		fmt.Fprintf(w, "data: %s\n\n", data)
		flusher.Flush()
		lastSeq = e.Sequence
	}
}

// GET /ready
func SystemReadiness(w http.ResponseWriter, r *http.Request) {
	if err := db.DB.Ping(); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready", "error": err.Error()})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}

// Helpers

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * 0.017453292519943295
	dLng := (lng2 - lng1) * 0.017453292519943295
	a := sin(dLat/2)*sin(dLat/2) + cos(lat1*0.017453292519943295)*cos(lat2*0.017453292519943295)*sin(dLng/2)*sin(dLng/2)
	c := 2 * atan2(sqrt(a), sqrt(1-a))
	return R * c
}

func sin(x float64) float64 {
	// Simple Taylor series for sin
	return x - x*x*x/6 + x*x*x*x*x/120 - x*x*x*x*x*x*x/5040
}

func cos(x float64) float64 {
	return sin(1.5707963267948966 - x)
}

func sqrt(x float64) float64 {
	if x <= 0 {
		return 0
	}
	z := x
	for i := 0; i < 100; i++ {
		z -= (z*z - x) / (2 * z)
	}
	return z
}

func atan2(y, x float64) float64 {
	if x > 0 {
		return atan(y / x)
	}
	if x < 0 && y >= 0 {
		return atan(y/x) + 3.141592653589793
	}
	if x < 0 && y < 0 {
		return atan(y/x) - 3.141592653589793
	}
	if x == 0 && y > 0 {
		return 1.5707963267948966
	}
	if x == 0 && y < 0 {
		return -1.5707963267948966
	}
	return 0
}

func atan(x float64) float64 {
	return x - x*x*x/3 + x*x*x*x*x/5 - x*x*x*x*x*x*x/7
}

func mustJSONStr(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}"}

