{"command": "create", "path": "/workspace/frontend/src/api.ts", "file_text": "const BASE = '/api';

function token(): string | null {
  return localStorage.getItem('token');
}

async function request(method: string, path: string, body?: unknown): Promise<Response> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const t = token();
  if (t) headers['Authorization'] = `Bearer ${t}`;

  const res = await fetch(BASE + path, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  if (res.status === 401) {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    if (window.location.pathname !== '/login') {
      window.location.href = '/login';
    }
  }
  return res;
}

export async function apiLogin(username: string, password: string) {
  const res = await request('POST', '/auth/login', { username, password });
  return res.json();
}

export async function apiGet<T = unknown>(path: string): Promise<T> {
  const res = await request('GET', path);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(err.message || err.error || 'Request failed');
  }
  return res.json();
}

export async function apiPost<T = unknown>(path: string, body?: unknown): Promise<T> {
  const res = await request('POST', path, body);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(err.message || err.error || 'Request failed');
  }
  return res.json();
}

export async function apiPut<T = unknown>(path: string, body?: unknown): Promise<T> {
  const res = await request('PUT', path, body);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(err.message || err.error || 'Request failed');
  }
  return res.json();
}

export async function apiDelete<T = unknown>(path: string): Promise<T> {
  const res = await request('DELETE', path);
  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(err.message || err.error || 'Request failed');
  }
  return res.json();
}"}

{"command": "create", "path": "/workspace/frontend/src/auth.tsx", "file_text": "import React, { createContext, useContext, useState, useCallback, useEffect, type ReactNode } from 'react';
import { apiLogin, apiGet } from './api';

export interface User {
  userId: string;
  username: string;
  roles: string[];
  currentRole?: string;
}

interface AuthContextType {
  user: User | null;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  switchRole: (role: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: async () => {},
  logout: () => {},
  switchRole: async () => {},
});

export function useAuth() {
  return useContext(AuthContext);
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem('user');
    return stored ? JSON.parse(stored) : null;
  });

  const login = useCallback(async (username: string, password: string) => {
    const data = await apiLogin(username, password);
    const token = data.data?.token || data.token;
    const u = data.data?.user || data.user;
    if (token) {
      localStorage.setItem('token', token);
    }
    if (u) {
      localStorage.setItem('user', JSON.stringify(u));
      setUser(u);
    }
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  }, []);

  const switchRole = useCallback(async (role: string) => {
    if (!user) return;
    const data = await apiPost<{ data: User }>('/auth/switch-role', { role });
    if (data.data) {
      localStorage.setItem('user', JSON.stringify(data.data));
      setUser(data.data);
    }
  }, [user]);

  useEffect(() => {
    const t = localStorage.getItem('token');
    if (t && !user) {
      apiGet<{ data: User }>('/auth/me')
        .then((data) => {
          if (data.data) {
            setUser(data.data);
            localStorage.setItem('user', JSON.stringify(data.data));
          }
        })
        .catch(() => {
          localStorage.removeItem('token');
        });
    }
  }, []);

  return (
    <AuthContext.Provider value={{ user, login, logout, switchRole }}>
      {children}
    </AuthContext.Provider>
  );
}"}

